package main

import (
	"context"
	"errors"
	"fmt"
	"os"
	"path/filepath"
	"strings"
	"sync"

	"google.golang.org/protobuf/types/known/structpb"

	"github.com/mellifera/mellifera/pkg/sdk"
	scannerv1 "github.com/mellifera/mellifera/proto/mellifera/scanner/v1"
)

// Compile-time assertion that scannerImpl satisfies sdk.Scanner (the one
// interface this feature ships — R8).
var _ sdk.Scanner = (*scannerImpl)(nil)

// scannerImpl is the server-side Scanner capability for directory-structured
// serial libraries. Scan walks the library root one level deep and streams
// DiscoveredFile (serial records before their episodes); Identify is a pure
// parse of one discovered file that stamps the serial-record marker facts
// (design.md §Interfaces §1) or the episode stamping facts (§2).
type scannerImpl struct {
	// facts carries the per-file facts the walk computed (sidecar association
	// needs the on-disk tree, which Identify cannot re-derive from a relative
	// path alone). The core ALWAYS calls Scan before Identify in the drain
	// (internal/scan persist), within the same plugin process, so the walk
	// populates the map the later Identify calls read. Deviation note:
	// base-scanner is stateless between RPCs; serial-scanner keeps this single
	// per-scan map because the sidecar contract (§Interfaces §2) is only
	// computable with tree context. On a miss (a foreign file Identify was
	// never shown), the facts degrade gracefully — see fileFactsFor.
	mu    sync.Mutex
	facts map[string]fileFacts
}

// fileFacts is what Identify stamps for one relative path. Exactly one of the
// record / episode views is populated per the `record` flag.
type fileFacts struct {
	record     bool
	backing    string // record: "directory" | "file"
	dirNameRaw string // record: the raw directory (or file) name
	seriesRel  string // the serial identity path (§Interfaces §1/§2)
	// seriesSidecars: record only — sidecars matching NO episode (§1).
	seriesSidecars []sidecarFact
	// sidecars: episode only — episode-linked sidecars with match basis (§2).
	sidecars []sidecarFact
}

// serialConfidence is the neutral confidence serial-scanner stamps, mirroring
// base-scanner's baseConfidence: the directory structure is a real, if generic,
// signal.
const serialConfidence = 0.5

// Scan resolves + validates the library root, enforces the `structure` scanner
// option (design.md §Interfaces §3 — the seeded serial module config carries
// {"structure": "series-directories"}; ANY other value, including an absent one,
// is a fatal config error), then streams one DiscoveredFile per serial record /
// episode on a bounded channel. The root resolution and config failures are the
// only hard errors; per-file problems (probe soft-fails, deep videos, junk) are
// handled inside scanTree and never abort the stream (AC-6).
func (s *scannerImpl) Scan(ctx context.Context, req *scannerv1.ScanRequest) (<-chan *scannerv1.DiscoveredFile, error) {
	root := req.GetLibraryPath()
	if root == "" {
		return nil, errors.New("serial-scanner: scan request has empty library_path")
	}
	structure := req.GetOptions().GetFields()["structure"].GetStringValue()
	if structure != structureSeriesDirectories {
		return nil, fmt.Errorf("serial-scanner: unsupported structure option %q (want %q)",
			structure, structureSeriesDirectories)
	}
	absRoot, err := resolveRoot(root)
	if err != nil {
		return nil, fmt.Errorf("serial-scanner: resolve library root: %w", err)
	}
	s.beginScan()
	ch := make(chan *scannerv1.DiscoveredFile, walkChanBound)
	go func() {
		defer close(ch)
		scanTree(ctx, s, absRoot, ch)
	}()
	return ch, nil
}

// Identify is the pure unary parse of one discovered file. For a serial record
// it stamps the marker facts (design.md §Interfaces §1): serial_record,
// dir_name_raw, backing, series_relative_path, series_sidecars (match_basis
// null). For an episode it stamps relative_path + extension (the base fields,
// base-scanner semantics) plus the episode stamping facts (§2):
// series_relative_path and sidecars (match_basis "sxxexx"|"bare_number").
// No I/O beyond the request (arch §3.1).
func (s *scannerImpl) Identify(_ context.Context, req *scannerv1.IdentifyRequest) (*scannerv1.IdentifyResult, error) {
	file := req.GetFile()
	rel := file.GetRelativePath()
	facts := s.fileFactsFor(rel)
	parsed, err := structpb.NewStruct(facts.parsed(rel))
	if err != nil {
		return nil, fmt.Errorf("serial-scanner: stamp facts for %q: %w", rel, err)
	}
	return &scannerv1.IdentifyResult{
		FileId:     file.GetFileId(),
		MediaType:  req.GetModuleType(),
		Parsed:     parsed,
		Confidence: serialConfidence,
		ParserName: "serial",
	}, nil
}

// parsed projects the facts into the parsed Struct shape the drain reads
// (internal/scan identifyParsed round-trips this through JSON).
func (f fileFacts) parsed(rel string) map[string]any {
	if f.record {
		return map[string]any{
			"serial_record":        true,
			"dir_name_raw":         f.dirNameRaw,
			"backing":              f.backing,
			"series_relative_path": f.seriesRel,
			"series_sidecars":      sidecarList(f.seriesSidecars),
		}
	}
	return map[string]any{
		"relative_path":        rel,
		"extension":            filepath.Ext(rel),
		"series_relative_path": f.seriesRel,
		"sidecars":             sidecarList(f.sidecars),
	}
}

// sidecarList renders sidecar facts as the JSON-shaped list structpb expects
// ({"relative_path", "kind", "language", "match_basis"}); a nil match_basis
// becomes JSON null (§Interfaces §1: serial-level match_basis: null).
func sidecarList(facts []sidecarFact) []any {
	list := make([]any, 0, len(facts))
	for _, sc := range facts {
		var basis any
		if sc.MatchBasis != nil {
			basis = *sc.MatchBasis
		}
		list = append(list, map[string]any{
			"relative_path": sc.RelativePath,
			"kind":          sc.Kind,
			"language":      sc.Language,
			"match_basis":   basis,
		})
	}
	return list
}

// beginScan installs a fresh facts map (one per Scan call).
func (s *scannerImpl) beginScan() {
	s.mu.Lock()
	defer s.mu.Unlock()
	s.facts = map[string]fileFacts{}
}

// registerFacts merges one serial's stamped facts into the scan's map. Called
// BEFORE the record is emitted: the core identifies each file as the stream
// drains, starting with the record.
func (s *scannerImpl) registerFacts(facts map[string]fileFacts) {
	s.mu.Lock()
	defer s.mu.Unlock()
	for rel, f := range facts {
		s.facts[rel] = f
	}
}

// fileFactsFor reads the facts for rel, degrading gracefully on a miss (a file
// this process never walked): the series-relative path is derived from the path
// shape (its first segment; the file itself when top-level) with no sidecars —
// never an error, never a panic.
func (s *scannerImpl) fileFactsFor(rel string) fileFacts {
	s.mu.Lock()
	defer s.mu.Unlock()
	if f, ok := s.facts[rel]; ok {
		return f
	}
	return fileFacts{seriesRel: deriveSeriesRel(rel)}
}

// deriveSeriesRel infers the serial identity path from a relative path alone:
// everything before the first slash, or the path itself for a top-level
// (file-backed-shaped) file.
func deriveSeriesRel(rel string) string {
	slashed := filepath.ToSlash(rel)
	if i := strings.IndexByte(slashed, '/'); i > 0 {
		return slashed[:i]
	}
	return rel
}

// resolveRoot absolutizes + cleans the configured root, resolves symlinks, and
// confirms it is an existing directory (replicated from
// plugins/base-scanner/scanner.go:78). The resolved absolute root is the anchor
// every candidate path is later checked against by withinRoot (AC-4).
func resolveRoot(root string) (string, error) {
	abs, err := filepath.Abs(filepath.Clean(root))
	if err != nil {
		return "", err
	}
	resolved, err := filepath.EvalSymlinks(abs)
	if err != nil {
		return "", err
	}
	info, err := os.Stat(resolved)
	if err != nil {
		return "", err
	}
	if !info.IsDir() {
		return "", errors.New("serial-scanner: library root is not a directory")
	}
	return resolved, nil
}
